.wrap{height:calc(var(--appsmith-ui-height)*1px);overflow-y:auto;overflow-x:hidden;padding:18px 26px 48px;}
.top{display:flex;align-items:flex-start;gap:40px;margin-bottom:4px;}
.fld label{display:block;font-size:14px;color:#60a5fa;font-weight:600;margin-bottom:8px;}
.fld select,.dateinput{background:#1e293b;color:#e2e8f0;border:1px solid #334155;border-radius:6px;padding:9px 12px;font-size:14px;min-width:300px;outline:none;cursor:pointer;height:40px;}
.fld select:focus{border-color:#3b82f6;}
.dateinput{display:flex;align-items:center;gap:8px;}
.dateinput .ph{color:#94a3b8;} .dateinput.has .ph{color:#e2e8f0;}
.dateinput .clr{margin-left:auto;color:#94a3b8;font-size:15px;padding:0 2px;}
.dateinput .clr:hover{color:#e2e8f0;}
.spacer{flex:1 1 auto;}
.addlink{color:#60a5fa;font-weight:700;font-size:14px;text-decoration:none;white-space:nowrap;margin-top:34px;cursor:pointer;}
.addlink:hover{text-decoration:underline;}
.pop{position:absolute;top:74px;left:0;z-index:50;background:#1e293b;border:1px solid #334155;border-radius:10px;box-shadow:0 12px 30px rgba(0,0,0,.5);padding:14px;width:340px;}
.pop .nav{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;}
.pop .nav b{font-size:15px;color:#f1f5f9;}
.pop .nav span{cursor:pointer;color:#cbd5e1;font-size:20px;padding:2px 10px;border-radius:6px;line-height:1;}
.pop .nav span:hover{background:#334155;}
.pop .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;}
.pop .grid b{text-align:center;padding:13px 0;border-radius:8px;font-size:14px;font-weight:600;color:#cbd5e1;cursor:pointer;}
.pop .grid b:hover{background:#334155;}
.pop .grid b.on{background:#2563eb;color:#fff;}
.msec{margin-top:34px;}
.mhead{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;}
.mhead h2{margin:0;font-size:26px;font-weight:800;color:#f1f5f9;letter-spacing:.2px;}
.editlink{color:#60a5fa;font-weight:600;font-size:14px;text-decoration:none;cursor:pointer;display:inline-flex;align-items:center;gap:6px;}
.editlink:hover{text-decoration:underline;}
table{width:100%;border-collapse:separate;border-spacing:0;font-size:14px;}
thead th{text-align:left;font-weight:700;color:#cbd5e1;padding:12px 18px;border-bottom:1px solid #334155;}
tbody td{padding:14px 18px;color:#e2e8f0;}
tbody td.v span{display:inline-block;min-width:130px;padding-bottom:5px;border-bottom:1px solid #334155;}
tbody tr:nth-child(odd) td{background:#1e293b;}
tbody tr:nth-child(even) td{background:transparent;}
.empty{padding:54px 20px;text-align:center;color:#94a3b8;}
.empty .big{font-size:15px;color:#cbd5e1;margin-bottom:6px;max-width:640px;margin-left:auto;margin-right:auto;} .empty .sm{font-size:13px;color:#64748b;}
.overlay{position:fixed;inset:0;background:rgba(2,6,23,.66);z-index:100;display:flex;align-items:center;justify-content:center;}
.modal{background:#1e293b;border:1px solid #334155;border-radius:12px;width:560px;max-width:92%;padding:26px 28px;box-shadow:0 24px 60px rgba(0,0,0,.6);}
.modal .mh{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;}
.modal .mh h3{margin:0;font-size:22px;font-weight:800;color:#f1f5f9;}
.modal .mh .x{cursor:pointer;color:#94a3b8;font-size:22px;line-height:1;}
.modal p{color:#cbd5e1;font-size:14px;line-height:1.5;margin:0 0 22px;}
.modal .row{display:flex;gap:20px;}
.modal .row .fld{flex:1;}
.modal .row .fld .req{color:#f87171;}
.modal select{width:100%;min-width:0;}
.modal .acts{display:flex;justify-content:flex-start;gap:14px;margin-top:44px;}
.btn{padding:11px 26px;border-radius:8px;font-size:15px;font-weight:600;cursor:pointer;border:1px solid #334155;}
.btn.cancel{background:transparent;color:#e2e8f0;}
.btn.primary{background:#2563eb;color:#fff;border-color:#2563eb;}
.btn.primary:hover{background:#1d4ed8;}
::-webkit-scrollbar{width:10px;height:10px;background:#0f172a;} ::-webkit-scrollbar-thumb{background:#1e293b;border-radius:4px;border:2px solid #0f172a;}

