function esc(s){return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}
var MONTHS=["January","February","March","April","May","June","July","August","September","October","November","December"];
var M3=["JAN","FEB","MAR","APR","MAY","JUN","JUL","AUG","SEP","OCT","NOV","DEC"];
var CAL='<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>';
var selAttr="ALL", selMonth="", pickerOpen=false, addOpen=false, pickerYear=(new Date()).getFullYear();

function C(){
  var all=(appsmith.model&&appsmith.model.rows)||[];
  var uom={}, ord={};
  all.forEach(function(r){
    if(r.Attribute){
      if(r.UoM!=null && uom[r.Attribute]==null) uom[r.Attribute]=r.UoM;
      var o=(r._order==null)?9999:Number(r._order);
      if(ord[r.Attribute]==null || o<ord[r.Attribute]) ord[r.Attribute]=o;
    }
  });
  var attrsAll=Object.keys(ord).sort(function(a,b){
    if(ord[a]!==ord[b]) return ord[a]-ord[b];
    return a.localeCompare(b);
  });
  var ms={};
  all.forEach(function(r){ var k=r.Month; if(k){var s=String(r._sort||""); if(!ms[k]||s>ms[k])ms[k]=s;}});
  var months=Object.keys(ms).sort(function(a,b){return ms[b].localeCompare(ms[a]);});
  var map={};
  all.forEach(function(r){ if(!map[r.Attribute])map[r.Attribute]={}; map[r.Attribute][r.Month]=r.Value;});
  return {attrsAll:attrsAll,uom:uom,months:months,map:map};
}

function fmtVal(v){ if(v==null||v==="") return "N/A"; return esc(v); }

function sectionsHtml(c){
  var attrs=(selAttr==="ALL")?c.attrsAll:(c.attrsAll.indexOf(selAttr)>=0?[selAttr]:[]);
  var months=c.months;
  if(selMonth){ months=months.filter(function(m){return m===selMonth;}); }
  if(!c.attrsAll.length){
    return '<div class="empty"><div class="big">The Location needs to have Attributes in order to allow for Production Data values to be entered.</div><div class="sm">No monthly attribute data for this location.</div></div>';
  }
  if(!months.length){
    return '<div class="empty"><div class="big">No monthly attribute data'+(selMonth?(' for '+esc(selMonth)):'')+'.</div><div class="sm">Use “Add Year/Months” to add periods.</div></div>';
  }
  return months.map(function(mo){
    var rows=attrs.map(function(a){
      var v=(c.map[a]||{})[mo];
      return '<tr><td class="a">'+esc(a)+'</td><td class="v"><span>'+fmtVal(v)+'</span></td><td class="u">'+esc(c.uom[a]||"")+'</td></tr>';
    }).join('');
    return '<div class="msec"><div class="mhead"><h2>'+esc(mo)+'</h2><a class="editlink" data-month="'+esc(mo)+'">✎ Edit</a></div>'
      +'<table><thead><tr><th style="width:42%">Attribute</th><th style="width:30%">Value</th><th style="width:28%">UoM</th></tr></thead><tbody>'+rows+'</tbody></table></div>';
  }).join('');
}

function pickerHtml(){
  if(!pickerOpen) return '';
  var cells=MONTHS.map(function(name,i){
    var on=(selMonth===name+" "+pickerYear);
    return '<b class="'+(on?"on":"")+'" data-m="'+i+'">'+M3[i]+'</b>';
  }).join('');
  return '<div class="pop" id="pop"><div class="nav"><span data-nav="-1">‹</span><b>'+pickerYear+'</b><span data-nav="1">›</span></div><div class="grid">'+cells+'</div></div>';
}

function addModalHtml(){
  if(!addOpen) return '';
  var nowY=(new Date()).getFullYear();
  var years=[]; for(var y=nowY+1;y>=nowY-6;y--) years.push(y);
  var yopts='<option value="">Choose year</option>'+years.map(function(y){return '<option value="'+y+'">'+y+'</option>';}).join('');
  var mopts='<option value="">Choose months</option>'+MONTHS.map(function(m,i){return '<option value="'+(i+1)+'">'+m+'</option>';}).join('');
  return '<div class="overlay" id="overlay"><div class="modal">'
    +'<div class="mh"><h3>Add Year/Months</h3><span class="x" id="addX">✕</span></div>'
    +'<p>Years and Months that are already part of your list will appear as disabled in the below dropdowns.</p>'
    +'<div class="row"><div class="fld"><label>Year <span class="req">*</span></label><select>'+yopts+'</select></div>'
    +'<div class="fld"><label>Months <span class="req">*</span></label><select>'+mopts+'</select></div></div>'
    +'<div class="acts"><button class="btn cancel" id="addCancel">Cancel</button><button class="btn primary" id="addSave">Add</button></div>'
    +'</div></div>';
}

function render(){
  var c=C();
  var m=appsmith.model||{};
  var opts='<option value="ALL"'+(selAttr==="ALL"?" selected":"")+'>All Attributes</option>'
    +c.attrsAll.map(function(a){return '<option value="'+esc(a)+'"'+(selAttr===a?" selected":"")+'>'+esc(a)+'</option>';}).join('');
  var dateCls='dateinput'+(selMonth?' has':'');
  var top='<div class="top">'
    +'<div class="fld"><label>Attribute</label><select id="attrSel">'+opts+'</select></div>'
    +'<div class="fld" style="position:relative"><label>Go to Month</label>'
      +'<div class="'+dateCls+'" id="dateInput">'+CAL+'<span class="ph">'+(selMonth?esc(selMonth):'All months')+'</span>'+(selMonth?'<span class="clr" id="clrMonth">✕</span>':'')+'</div>'
      +pickerHtml()
    +'</div>'
    +'<div class="spacer"></div>'
    +'<a class="addlink" id="addLink">Add Year/Months</a>'
  +'</div>';
  var body;
  if(m.isLoading){ body='<div class="empty"><div class="big">Loading…</div></div>'; }
  else { body=sectionsHtml(c); }
  var root=document.getElementById("root"); if(!root) return;
  root.innerHTML='<div class="wrap">'+top+body+'</div>'+addModalHtml();
  bind();
}

function bind(){
  var sel=document.getElementById("attrSel");
  if(sel) sel.onchange=function(e){ selAttr=e.target.value; render(); };
  var di=document.getElementById("dateInput");
  if(di) di.onclick=function(e){ if(e.target && e.target.id==="clrMonth") return; pickerOpen=!pickerOpen; render(); };
  var clr=document.getElementById("clrMonth");
  if(clr) clr.onclick=function(e){ e.stopPropagation(); selMonth=""; pickerOpen=false; render(); };
  var pop=document.getElementById("pop");
  if(pop){
    var navs=pop.querySelectorAll("[data-nav]");
    for(var i=0;i<navs.length;i++){ (function(s){ s.onclick=function(){ pickerYear+=parseInt(s.getAttribute("data-nav"),10); render(); }; })(navs[i]); }
    var mbs=pop.querySelectorAll("[data-m]");
    for(var j=0;j<mbs.length;j++){ (function(b){ b.onclick=function(){ var k=parseInt(b.getAttribute("data-m"),10); selMonth=MONTHS[k]+" "+pickerYear; pickerOpen=false; render(); }; })(mbs[j]); }
  }
  var add=document.getElementById("addLink");
  if(add) add.onclick=function(){ addOpen=true; render(); };
  var ax=document.getElementById("addX"), ac=document.getElementById("addCancel"), ov=document.getElementById("overlay"), asv=document.getElementById("addSave");
  function closeAdd(){ addOpen=false; render(); }
  if(ax) ax.onclick=closeAdd; if(ac) ac.onclick=closeAdd; if(asv) asv.onclick=closeAdd;
  if(ov) ov.onclick=function(e){ if(e.target===ov) closeAdd(); };
}

appsmith.onReady(function(){ render(); appsmith.onModelChange(render); });

